// src/api/tmdb.js

export async function getLatestMovies() {
  const TMDB_API_KEY = '7b62a6d8f7b7f0e49308f8c6ceb4cf80'; 
  const KOBIS_API_KEY = 'b5b0cb84dc79a8589d6d6bee3a960b00'; 
  
  // 💡 실시간으로 '어제' 날짜의 박스오피스 데이터를 동적으로 계산 (예: 20260909)
  const d = new Date();
  d.setDate(d.getDate() - 1);
  const targetDt = d.toISOString().slice(0, 10).replace(/-/g, '');

  try {
    const kobisUrl = `https://www.kobis.or.kr/kobisopenapi/webservice/rest/boxoffice/searchDailyBoxOfficeList.json?key=${KOBIS_API_KEY}&targetDt=${targetDt}`;
    
    const kobisRes = await fetch(kobisUrl);
    const kobisData = await kobisRes.json();
    
    // KOBIS 데이터가 정상적으로 오지 않을 경우 (키 미활성화 등)
    if (!kobisData.boxOfficeResult || !kobisData.boxOfficeResult.dailyBoxOfficeList) {
      console.warn("KOBIS API 실시간 연동 대기 중입니다. 잠시 후 최신 영화로 자동 업데이트됩니다.");
      return getFallbackMovies();
    }

    const boxOfficeList = kobisData.boxOfficeResult.dailyBoxOfficeList;

    const moviesWithPosters = await Promise.all(
      boxOfficeList.map(async (movie, index) => {
        const query = encodeURIComponent(movie.movieNm);
        const tmdbUrl = `https://api.themoviedb.org/3/search/movie?api_key=${TMDB_API_KEY}&language=ko-KR&query=${query}`;
        
        try {
          const tmdbRes = await fetch(tmdbUrl);
          const tmdbData = await tmdbRes.json();
          const match = tmdbData.results?.[0];

          return {
            id: movie.movieCd || index,
            title: movie.movieNm,
            rank: movie.rank,
            audiAcc: movie.audiAcc,
            openDt: movie.openDt,
            rate: movie.salesShare + '%',
            poster_path: match?.poster_path || '',
            backdrop_path: match?.backdrop_path || ''
          };
        } catch {
          return {
            id: movie.movieCd || index,
            title: movie.movieNm,
            rank: movie.rank,
            rate: '0%',
            poster_path: '',
            backdrop_path: ''
          };
        }
      })
    );

    return moviesWithPosters;
  } catch (error) {
    console.error('API 연동 에러:', error);
    return getFallbackMovies();
  }
}

function getFallbackMovies() {
  return [
    { id: 1, title: "인사이드 아웃 2", openDt: "2024-06-12", poster_path: "/vpnVM9B6NMmQpWeZvzLvDESb2QY.jpg", backdrop_path: "/xg2bc3DwrViaDWj6lBoq1mSYAKM.jpg" },
    { id: 2, title: "범죄도시4", openDt: "2024-04-24", poster_path: "/z1pufUDaUixWwIdXpeF54g2nS4G.jpg", backdrop_path: "/vWzSuIZmNqMvI00sUSkFb9vMcVm.jpg" },
    { id: 3, title: "파묘", openDt: "2024-02-22", poster_path: "/lWjrLW8YBWDvvnbz2rW1kUaJ70P.jpg", backdrop_path: "/xOMo8DxID7PBBtT0q1hXo8sN7uG.jpg" },
    { id: 4, title: "웡카", openDt: "2024-01-31", poster_path: "/qhb1qYhjpypsM13k0e2sY1K59pW.jpg", backdrop_path: "/yyFc8UA5fscIAGlIe9qse41bZ21.jpg" },
    { id: 5, title: "듄: 파트 2", openDt: "2024-02-28", poster_path: "/8b8R8l88Qje9dn9OE8PY05Nxl1X.jpg", backdrop_path: "/xOMo8DxID7PBBtT0q1hXo8sN7uG.jpg" }
  ];
}
